   368  int
   369  sc_pkcs15_read_certificate(struct sc_pkcs15_card *p15card, const struct sc_pkcs15_cert_info *info,
   370                  int private_obj, struct sc_pkcs15_cert **cert_out)
   371  {
   372          struct sc_context *ctx = NULL;
   373          struct sc_pkcs15_cert *cert = NULL;
   374          struct sc_pkcs15_der der;
   375          int r;
   376
   377          if (p15card == NULL || info == NULL || cert_out == NULL) {
   378                  return SC_ERROR_INVALID_ARGUMENTS;
   379          }
   380          ctx = p15card->card->ctx;
   381          LOG_FUNC_CALLED(ctx);
   382
   383          if (info->value.len && info->value.value)   {
   384                  sc_der_copy(&der, &info->value);
   385          }
   386          else if (info->path.len) {
   387                  r = sc_pkcs15_read_file(p15card, &info->path, &der.value, &der.len, private_obj);
   388                  LOG_TEST_RET(ctx, r, "Unable to read certificate file.");
   389          }
   390          else   {
   391                  LOG_FUNC_RETURN(ctx, SC_ERROR_OBJECT_NOT_FOUND);
   392          }
   393
   394          cert = malloc(sizeof(struct sc_pkcs15_cert));
   395          if (cert == NULL) {
   396                  free(der.value);
   397                  LOG_FUNC_RETURN(ctx, SC_ERROR_OUT_OF_MEMORY);
   398          }
   399          memset(cert, 0, sizeof(struct sc_pkcs15_cert));
   400          if (parse_x509_cert(ctx, &der, cert)) {
   401                  free(der.value);
   402                  sc_pkcs15_free_certificate(cert);
   403                  LOG_FUNC_RETURN(ctx, SC_ERROR_INVALID_ASN1_OBJECT);
   404          }
   405          free(der.value);
   406
   407          *cert_out = cert;
   408          LOG_FUNC_RETURN(ctx, SC_SUCCESS);
   409  }
